%[text] %[text:anchor:H_623A23AE] ### Nine-noded biquadratic Reissner-Mindlin elements
%[text] %[text:anchor:H_7022F944] #### Solution of the linear equation system
numDOFsQ2 = 2*numNodesQ2;
uQ2 = zeros(numDOFsQ2, 1);
uQ2(freeDOFsQ2, 1) = KQ2(freeDOFsQ2, freeDOFsQ2)\FQ2(freeDOFsQ2);
%[text] %[text:anchor:H_BAE22716] #### Visualization of the solution in terms of the vertical displacement field
mshCurrQ2 = mshQ2;
scaling = 1; %[control:slider:7403]{"position":[11,12]}
mshCurrQ2.nodes(:, 3) = mshCurrQ2.nodes(:, 3) + ...
    scaling*uQ2(1:3:end, 1);
numVertices = numel(mshQ1.nodes(:, 1));
figure, %[output:3ce91e51]
plotMesh2d(mshCurrQ2, numVertices, false); %[output:3ce91e51]
hold on; %[output:3ce91e51]
fsurf(wExSubs, [X0 XLx Y0 YLy], FaceColor=[203 65 84]/255, ... %[output:3ce91e51]
    FaceAlpha=0.5, LineStyle="none"); %[output:3ce91e51]
scalVer = 1;
[xsQ2, ysQ2, zsQ2] = createSupports3D(mshCurrQ2.nodes, homDOFsQ2, scalVer);
for k = 1:length(xsQ2(:, 1))
    plot3(xsQ2(k, :), ysQ2(k, :), zsQ2(k, :), 'Linewidth', 2, ... %[output:3ce91e51]
        'Color', 'black'); %[output:3ce91e51]
end
hold off; %[output:3ce91e51]
axis equal; %[output:3ce91e51]
xlabel("x") %[output:3ce91e51]
ylabel("y") %[output:3ce91e51]
zlabel("$\beta_y$", Interpreter="latex") %[output:3ce91e51]
legend("FEM", "", "analytical", Location="best") %[output:3ce91e51]
title("Plate's deformation using Q2 elements") %[output:3ce91e51]
%[text] %[text:anchor:H_1474271A] ### Visualization of the solution in terms of the rotational field
mshCurrQ2Betay = mshQ2;
scaling = 1; %[control:slider:077c]{"position":[11,12]}
mshCurrQ2Betay.nodes(:, 3) = mshCurrQ2Betay.nodes(:, 3) + ...
    scaling*uQ2(3:3:end);
numVertices = numel(mshQ2.nodes(:, 1));
figure, %[output:8d212e9f]
plotMesh2d(mshCurrQ2Betay, numVertices, false); %[output:8d212e9f]
hold on; %[output:8d212e9f]
fsurf(betayExSubs, [X0 XLx Y0 YLy], FaceColor=[203 65 84]/255, ... %[output:8d212e9f]
    FaceAlpha=0.5, LineStyle="none"); %[output:8d212e9f]
scalVer = 1;
[xsQ2, ysQ2, zsQ2] = createSupports3D(mshCurrQ2Betay.nodes, homDOFsQ2, scalVer);
for k = 1:length(xsQ2(:, 1))
    plot3(xsQ2(k, :), ysQ2(k, :), zsQ2(k, :), 'Linewidth', 2, ... %[output:8d212e9f]
        'Color', 'black'); %[output:8d212e9f]
end
hold off; %[output:8d212e9f]
axis equal; %[output:8d212e9f]
xlabel("x") %[output:8d212e9f]
ylabel("y") %[output:8d212e9f]
zlabel("$\beta_y$", Interpreter="latex") %[output:8d212e9f]
legend("FEM", "", "analytical", Location="best") %[output:8d212e9f]
title("Distribution of rotation field $\beta_y$ using Q2 elements", ... %[output:group:0d170664] %[output:8d212e9f]
    Interpreter="latex") %[output:group:0d170664] %[output:8d212e9f]
